package com.neu.riketiku.shijuan;import com.neu.riketiku.renzheng.RenZhengYongHu;import jakarta.validation.Valid;import java.util.List;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/teacher/papers") public class PaperController{private final PaperService service;public PaperController(PaperService service){this.service=service;}@GetMapping public List<PaperDtos.ListItem>list(@AuthenticationPrincipal RenZhengYongHu u){return service.list(u.id());}@GetMapping("/questions")public List<PaperDtos.QuestionOption>questions(@AuthenticationPrincipal RenZhengYongHu u,@RequestParam long subjectId,@RequestParam(required=false)Long knowledgePointId,@RequestParam(required=false)String questionType,@RequestParam(required=false)Integer difficulty,@RequestParam(required=false)String keyword){return service.questions(u.id(),subjectId,knowledgePointId,questionType,difficulty,keyword);}@GetMapping("/{id}")public PaperDtos.Paper detail(@AuthenticationPrincipal RenZhengYongHu u,@PathVariable long id){return service.detail(u.id(),id);}@PostMapping public PaperDtos.Paper save(@AuthenticationPrincipal RenZhengYongHu u,@Valid @RequestBody PaperDtos.Save r){return service.save(u.id(),r);}@PostMapping("/rule")public PaperDtos.Paper rule(@AuthenticationPrincipal RenZhengYongHu u,@Valid @RequestBody PaperDtos.Rule r){return service.rule(u.id(),r);}}
